it('SUPPORT common intake: unlisted company first-time caller is registered and receives normal Work',async()=>{
 const requestId=randomUUID(),input={requestId,serviceId:ids.service,symptom:'ログイン方法がわかりません',caller:{kind:'NEW' as const,organizationName:'会員リスト未掲載の取引先',displayName:'初回 問合',distinctPersonConfirmed:false}};
 const event=await s.createEvent(a,input),retry=await s.createEvent(a,input);expect(retry.id).toBe(event.id);
 const detail=await q.detail(a,event.id);expect(detail.person.displayName).toBe('初回 問合');expect(detail.organization.name).toBe('会員リスト未掲載の取引先');expect(detail.affiliationWasNewAtIntake).toBe(true);
 expect((await db.admin.query('select count(*)::int n from factact.people where display_name=$1',['初回 問合'])).rows[0].n).toBe(1);
 expect((await db.admin.query("select metadata_json->>'reliability' as reliability from factact.audit_events where aggregate_id=$1 and event_type='SUPPORT_CONTACT_REGISTERED'",[event.id])).rows[0].reliability).toBe('UNVERIFIED');
 const evaluated=await s.evaluate(a,event.id,'REQUIRED','会員リストへの掲載とは無関係に通常対応');expect(evaluated.work?.status).toBe('OPEN');
 expect(evaluated.work?.title).toBe('初回 問合さんからの問い合わせ');
 await s.recordSupportResponse(a,evaluated.work!.id,{requestId:randomUUID(),expectedLifecycleRevision:0,expectedRecordRevision:0,responseText:'ログイン方法を案内した',disposition:'COMPLETED',followUpAt:null,close:{outcome:'RESOLVED',closeReason:'回答完了',confirmsOutstandingResponsibilityEnded:true}});
 expect((await q.detail(a,event.id)).work?.status).toBe('COMPLETED');
});
it('first-time caller registration reuses the affiliation and rejects unchecked duplicates',async()=>{
 const newEvent=await s.createEvent(a,{requestId:randomUUID(),serviceId:ids.service,symptom:'PCの質問',caller:{kind:'NEW',organizationName:'二社目',displayName:'山田 太郎',distinctPersonConfirmed:false}});
 const orgId=(await db.admin.query("select organization_id from factact.people where display_name='山田 太郎'")).rows[0].organization_id;
 await expect(s.createEvent(a,{requestId:randomUUID(),serviceId:ids.service,symptom:'質問',caller:{kind:'NEW',organizationId:orgId,displayName:'山田 太郎',distinctPersonConfirmed:false}})).rejects.toMatchObject({code:'DUPLICATE_PERSON'});
 await expect(s.createEvent(a,{requestId:randomUUID(),serviceId:ids.service,symptom:'質問',caller:{kind:'NEW',organizationName:'二社目',displayName:'別人',distinctPersonConfirmed:false}})).rejects.toMatchObject({code:'DUPLICATE_ORGANIZATION'});
 const sameOrg=await s.createEvent(a,{requestId:randomUUID(),serviceId:ids.service,symptom:'別のお名前',caller:{kind:'NEW',organizationId:orgId,displayName:'鈴木 花子',distinctPersonConfirmed:false}});
 expect(sameOrg.id).not.toBe(newEvent.id);
 expect((await db.admin.query('select count(*)::int n from factact.organizations where name=$1',['二社目'])).rows[0].n).toBe(1);
});
it('parallel intake with the same new affiliation does not silently create duplicates',async()=>{
 const make=(n:string)=>s.createEvent(a,{requestId:randomUUID(),serviceId:ids.service,symptom:n,caller:{kind:'NEW',organizationName:'同時受付会社',displayName:'同時 担当',distinctPersonConfirmed:false}});
 const outcomes=await Promise.allSettled([make('一件目'),make('二件目')]);
 expect(outcomes.filter(x=>x.status==='fulfilled')).toHaveLength(1);
 expect(outcomes.filter(x=>x.status==='rejected')).toMatchObject([{status:'rejected',reason:{code:'DUPLICATE_ORGANIZATION'}}]);
 expect((await db.admin.query("select count(*)::int n from factact.organizations where name='同時受付会社'")).rows[0].n).toBe(1);
});
