// Existing V1 behavior remains covered as historical compatibility. Slice 2 V2 cases create their own Work below.
async function work(){const e=await intake();const r=await s.evaluate(a,e.id,'REQUIRED','利用対象と症状の確認・案内が必要');await db.admin.query('update factact.work set lifecycle_version=1 where id=$1',[r.work!.id]);return{e,w:{...r.work!,lifecycleVersion:1}};}
async function workV2(){const e=await intake();const r=await s.evaluate(a,e.id,'REQUIRED','利用対象と症状の確認・案内が必要');return{e,w:r.work!};}
async function joinFact(){const e=await j.createJoinEvent(a,{organizationId:ids.organization,personId:ids.person,serviceId:ids.service,joinDate:'2026-10-02'});const r=await j.evaluateJoinRequirements(a,e.eventId),w=r.works[0]!;const p=await j.startAssignDeviceAction(a,{workId:w.id,deviceId:ids.device,executionSummary:'実機確認・引き渡し済み',effectiveFrom:'2026-10-01T07:00:00.000Z'});await j.verifyChange(a,p.changeId,'本人・実機を確認');return {workId:w.id,relation:await j.commitChange(a,p.changeId)};}
async function setReadRoles(roles:Operator['roles']){await db.admin.query('delete from factact.operator_roles where tenant_id=$1 and operator_id=$2',[ids.tenant,ids.operator]);for(const role of roles)await db.admin.query('insert into factact.operator_roles values($1,$2,$3)',[ids.tenant,ids.operator,role]);}
it('SUPPORT Read Authority v1 uses current Roles and remains separate from Command Authority',async()=>{const e=await intake();for(const role of ['ADMIN','OPERATOR','REVIEWER'] as const){await setReadRoles([role]);expect((await q.detail(a,e.id)).event.id).toBe(e.id);expect((await q.responsibility(a)).myWork).toEqual([]);}await expect(s.createEvent(a,{requestId:randomUUID(),personId:ids.person,serviceId:ids.service,symptom:'reviewer cannot execute'})).rejects.toMatchObject({code:'FORBIDDEN'});await setReadRoles([]);await expect(q.detail(a,e.id)).rejects.toMatchObject({code:'FORBIDDEN'});await expect(q.responsibility(a)).rejects.toMatchObject({code:'FORBIDDEN'});await db.admin.query("update factact.operators set status='INACTIVE' where id=$1",[ids.operator]);await expect(q.list(a)).rejects.toMatchObject({code:'NOT_FOUND'});await expect(q.responsibility(a)).rejects.toMatchObject({code:'NOT_FOUND'});});
it('Slice 3A derives My Work, Waiting, follow-up reasons and Owner Gap without writes',async()=>{
 const first=await workV2(),second=await workV2(),third=await workV2(),ownerId=randomUUID();
 await s.setWaiting(a,first.w.id,{requestId:randomUUID(),expectedRevision:0,party:'利用者',reason:'回答待ち',nextAction:'利用者へ確認する'});
 await s.setFollowUp(a,second.w.id,{requestId:randomUUID(),expectedRevision:0,followUpAt:'2026-10-01T09:00:00.000Z',sourceType:'HUMAN_DECISION',basisText:'担当者判断',reason:'時刻に確認'});
 await s.setFollowUp(a,third.w.id,{requestId:randomUUID(),expectedRevision:0,followUpAt:'2026-10-01T09:00:00.001Z',sourceType:'HUMAN_DECISION',basisText:'担当者判断',reason:'将来確認'});
 await db.admin.query("insert into factact.operators(id,tenant_id,email,display_name,status) values($1,$2,'unavailable@example.invalid','前担当者','INACTIVE')",[ownerId,ids.tenant]);
 await db.admin.query('update factact.work set work_owner_operator_id=$2 where id=$1',[third.w.id,ownerId]);
 const auditBefore=(await db.admin.query('select count(*)::int n from factact.audit_events')).rows[0].n,view=await q.responsibility(a);
 expect(view.clock).toBe('2026-10-01T09:00:00.000Z');expect(new Set(view.myWork.map(x=>x.workId))).toEqual(new Set([first.w.id,second.w.id]));
 expect(view.waiting.map(x=>x.workId)).toEqual([first.w.id]);
 expect(view.needsFollowUp.find(x=>x.workId===first.w.id)?.reasons).toEqual(['WAITING_FOLLOW_UP_UNSET']);
 expect(view.needsFollowUp.find(x=>x.workId===second.w.id)?.reasons).toEqual(['FOLLOW_UP_REACHED']);
 expect(view.needsFollowUp.find(x=>x.workId===third.w.id)?.reasons).toEqual(['OWNER_UNAVAILABLE']);
 expect(view.ownerGap[0]).toMatchObject({workId:third.w.id,ownerName:'前担当者',ownerStatus:'INACTIVE'});
 expect((await db.admin.query('select count(*)::int n from factact.audit_events')).rows[0].n).toBe(auditBefore);
 expect((await db.admin.query("select count(*)::int n from factact.work where status='COMPLETED'")).rows[0].n).toBe(0);
});
