 await s.confirmContextDevice(a,w.id,{requestId:randomUUID(),expectedRevision:0,deviceId:ids.device,confirmationSource:'OPERATOR'});v=await q.detail(a,e.id);expect(v.deviceComparison).toMatchObject({result:'MATCH',registry:{deviceId:ids.device,assetTag:'PC-0073'},target:{deviceId:ids.device,assetTag:'PC-0073',source:'OPERATOR'},targetUnidentified:false});
