 const other=randomUUID();await db.admin.query("insert into factact.devices(id,tenant_id,asset_tag,display_name,device_status) values($1,$2,'PC-0099','Temporary PC','AVAILABLE')",[other,ids.tenant]);await s.correctContextDevice(a,w.id,{requestId:randomUUID(),expectedRevision:1,deviceId:other,confirmationSource:'CALLER',reason:'本人が一時借用端末を使用'});v=await q.detail(a,e.id);expect(v.deviceComparison).toMatchObject({result:'DIFFERENT',registry:{deviceId:replacementId,assetTag:'PC-0088'},target:{deviceId:other,assetTag:'PC-0099',source:'CALLER'}});
 await s.endContextDevice(a,w.id,{requestId:randomUUID(),expectedRevision:2,reason:'対象を再確認するため'});expect((await q.detail(a,e.id)).deviceComparison).toMatchObject({result:'UNCONFIRMED',target:null,targetUnidentified:false});
