 await expect(s.recordSupportResponse(a,w.id,{requestId:firstRequest,expectedLifecycleRevision:0,expectedRecordRevision:0,responseText:'初回対応を完了',disposition:'COMPLETED',followUpAt:null,close:{outcome:'RESOLVED',closeReason:'初回解決',confirmsOutstandingResponsibilityEnded:true}})).resolves.toMatchObject({requestId:firstRequest});
